  const extractEmails = (obj) => {
    const found = new Set();
    const pattern = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;

    const walk = (value, key = '') => {
      if (value == null) return;

      if (Array.isArray(value)) {
        for (const item of value) walk(item, key);
        return;
      }

      if (typeof value === 'object') {
        for (const [k, v] of Object.entries(value)) walk(v, k);
        return;
      }

      if (typeof value === 'string' && /email/i.test(key)) {
        for (const email of value.match(pattern) || []) {
          found.add(email.trim().toLowerCase());
        }
      }
    };

    walk(obj);
    return [...found];
  };

  const leadEmails = extractEmails($json);
  const existingRows = $('Get row(s) in roofing sheet').all();

  const existingEmails = new Set(
    existingRows.flatMap(item => extractEmails(item.json))
  );

  return leadEmails.some(email => existingEmails.has(email));
})() }}

parameters.jsCode:
/*
  Lead deduplication for n8n.

  Required upstream nodes:
  - Merge: Input 1 = uploaded Excel rows
  - Get Roofing
  - Get Kitchen
  - Get HVAC
  - Get Filtered Leads

  Output:
  - One summary item
  - Accepted, unique lead items
  - Duplicate counts and reasons in the summary
*/

const CONFIG = {
  emailHeaders: [
    'email',
    'e-mail',
    'email address',
    'email_address',
    'emails'
  ],

  categoryHeaders: [
    'category',
    'niche',
    'industry',
    'type',
    'subtypes',
    'query',
    'search query',
    'search_query'
  ],

  sheetNodes: [
  {
    node: 'Get row(s) in roofing sheet',
    category: 'roofing'
  },
  {
    node: 'Get row(s) in Kitchen Remodeling sheet',
    category: 'kitchen'
  },
  {
    node: 'Get row(s) in HVAC sheet',
    category: 'hvac'
  },
  {
    node: 'Get row(s) in Filtered leads sheet',
    category: 'filtered'
  }
]
};

// Normalize column names such as Email, email, and EMAIL.
function normalizeKey(key) {
  return String(key ?? '')
    .trim()
    .toLowerCase()
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ');
}

// Find email addresses only in explicitly named email columns.
function getEmails(row) {
  const emails = new Set();

  for (const [key, value] of Object.entries(row ?? {})) {
    if (!CONFIG.emailHeaders.includes(normalizeKey(key))) continue;

    const values = Array.isArray(value) ? value : [value];

    for (const entry of values) {
      if (typeof entry !== 'string') continue;

      for (const candidate of entry.split(/[;,\s]+/)) {
        const email = candidate.trim().toLowerCase();

        if (
          /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$/i.test(email)
        ) {
          emails.add(email);
        }
      }
    }
  }

  return [...emails];
}

// Use explicit category keywords. Anything ambiguous goes to
// Filtered leads instead of guessing.
function classify(row) {
  const text = Object.entries(row ?? {})
    .filter(([key]) => CONFIG.categoryHeaders.includes(normalizeKey(key)))
    .map(([, value]) => {
      if (Array.isArray(value)) return value.join(' ');
      return String(value ?? '');
    })
    .join(' ')
    .toLowerCase();

  const hasRoofing = /\b(roofing|roofer|roofers|roof contractor|roof contractors)\b/.test(text);

  const hasKitchen =
    /\b(kitchen remodeling|kitchen remodeler|kitchen renovation|kitchen renovations|kitchen contractor|kitchen contractors)\b/.test(text);

  const hasHVAC =
    /\b(hvac|heating and cooling|heating ventilation air conditioning|air conditioning contractor|air conditioning contractors)\b/.test(text);

  const matches = [
    hasRoofing && 'roofing',
    hasKitchen && 'kitchen',
    hasHVAC && 'hvac'
  ].filter(Boolean);

  // Never guess if category evidence is absent or contradictory.
  return matches.length === 1 ? matches[0] : 'filtered';
}

// Retrieve all existing rows from each destination sheet.
const existingEmailsBySheet = new Map();
const allExistingEmails = new Set();

for (const config of CONFIG.sheetNodes) {
  const rows = $(config.node).all();
  const emails = new Set();

  for (const item of rows) {
    for (const email of getEmails(item.json)) {
      emails.add(email);
      allExistingEmails.add(email);
    }
  }

  existingEmailsBySheet.set(config.category, emails);
}

// The Merge node must preserve the uploaded Excel rows on Input 1.
const uploadedRows = $input.all();

const seenInUpload = new Set();
const accepted = [];

let missingEmailCount = 0;
let duplicateWithinUpload = 0;
let duplicateInSheets = 0;
let ambiguousCategoryCount = 0;

for (const item of uploadedRows) {
  const row = item.json;
  const emails = getEmails(row);

  if (emails.length === 0) {
    missingEmailCount++;
    continue;
  }

  // Multiple distinct email addresses in a row are ambiguous.
  // Do not silently choose one as the identity of the lead.
  if (emails.length !== 1) {
    missingEmailCount++;
    continue;
  }

  const email = emails[0];

  if (seenInUpload.has(email)) {
    duplicateWithinUpload++;
    continue;
  }

  // Mark it seen even if it already exists in the database.
  // This also prevents repeated copies of an existing lead
  // from being counted as new leads.
  seenInUpload.add(email);

  if (allExistingEmails.has(email)) {
    duplicateInSheets++;
    continue;
  }

  const category = classify(row);

  if (category === 'filtered') {
    ambiguousCategoryCount++;
  }

  accepted.push({
    json: {
      ...row,
      email,
      lead_category: category,
      dedupe_status: 'unique_new_lead'
    }
  });
}

// Return a summary item plus the accepted leads.
// Route the summary away from your Append Row nodes.
return [
  {
    json: {
      record_type: 'summary',
      uploaded_rows: uploadedRows.length,
      accepted_unique_leads: accepted.length,
      duplicates_within_upload: duplicateWithinUpload,
      duplicates_already_in_sheets: duplicateInSheets,
      rows_without_one_unambiguous_email: missingEmailCount,
      leads_sent_to_filtered_category: ambiguousCategoryCount,
      total_duplicates_removed:
        duplicateWithinUpload + duplicateInSheets
    }
  },
  ...accepted
];

const pages = $input.all().map(item => item.json);

const workflows = [];
for (const page of pages) {
  if (Array.isArray(page.data)) workflows.push(...page.data);
}

const now = new Date();

const dateFormatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});

const timeFormatter = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Kolkata',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
});

const backupDate = dateFormatter.format(now);
const backupTime = timeFormatter.format(now);
const executionId = String($execution?.id || Date.now());

const backup = {
  backupVersion: 1,
  backupCreatedAt: now.toISOString(),
  backupCreatedAtIST: `${backupDate} ${backupTime} IST`,
  source: {
    n8nBaseUrl: 'https://n8n.flowexa.space',
    api: '/api/v1/workflows',
  },
  workflowCount: workflows.length,
  workflows,
  notes: [
    'Generated automatically from the n8n REST API.',
    'Credential secret values are not included by the workflow API response; credentials must be recreated/reconnected after a disaster restore.',
    'Keep the GitHub repository PRIVATE, especially if any workflow contains hard-coded secrets in node parameters.'
  ]
};

const json = JSON.stringify(backup, null, 2);
const githubOwner = 'saudagarzeeshan25-commits';
const githubRepo = 'N8N-hostinger-Back-Up';
const githubBranch = 'main';

return [{
